import fs from "node:fs";
import path from "node:path";

const root =
  process.cwd();

const packName =
  "Animated Effects UI Polish Pack 12 Structural";

const styleRelative =
  "artifacts/animated-effects/src/style.css";

const pack06Relative =
  "artifacts/animated-effects/src/pack06/install.ts";

const styleFile =
  path.join(
    root,
    styleRelative,
  );

const pack06File =
  path.join(
    root,
    pack06Relative,
  );

const marker =
  "AE_UI_POLISH_PACK_12_STRUCTURAL_START";

function fail(
  message,
) {
  console.error(
    "\nERROR:",
    message,
  );
  process.exit(
    1,
  );
}

if (
  !fs.existsSync(
    path.join(
      root,
      "pnpm-workspace.yaml",
    ),
  )
) {
  fail(
    "Uruchom z katalogu głównego aplikacja-turnieje-live.",
  );
}

for (
  const file of [
    styleFile,
    pack06File,
  ]
) {
  if (
    !fs.existsSync(
      file,
    )
  ) {
    fail(
      "Brak wymaganego pliku: " +
      path.relative(
        root,
        file,
      ),
    );
  }
}

const currentStyle =
  fs.readFileSync(
    styleFile,
    "utf8",
  );

if (
  !currentStyle.includes(
    "AE_UI_POLISH_PACK_11_COMPACT_START",
  )
) {
  fail(
    "Pack 12 wymaga wcześniej zainstalowanego UI Polish Pack 11.",
  );
}

if (
  currentStyle.includes(
    marker,
  )
) {
  console.log(
    "UI Polish Pack 12 jest już zainstalowany.",
  );
  process.exit(
    0,
  );
}

const stamp =
  new Date()
    .toISOString()
    .replace(
      /[:.]/g,
      "-",
    )
    .replace(
      "T",
      "_",
    )
    .replace(
      "Z",
      "",
    );

const backupRoot =
  path.join(
    root,
    ".ae-pack-backup",
    `pack-12-ui-structural-${stamp}`,
  );

for (
  const relative of [
    styleRelative,
    pack06Relative,
  ]
) {
  const source =
    path.join(
      root,
      relative,
    );

  const backup =
    path.join(
      backupRoot,
      relative,
    );

  fs.mkdirSync(
    path.dirname(
      backup,
    ),
    {
      recursive:
        true,
    },
  );

  fs.copyFileSync(
    source,
    backup,
  );
}

let pack06 =
  fs.readFileSync(
    pack06File,
    "utf8",
  );

if (
  pack06.includes(
    "ae-pack12-library-tools",
  )
) {
  fail(
    "pack06/install.ts wygląda na już zmodyfikowany przez Pack 12, ale marker CSS nie istnieje. Użyj rollbacku albo sprawdź pliki.",
  );
}

const start =
  pack06.indexOf(
    "function addLibraryUi():void{",
  );

const end =
  pack06.indexOf(
    "function addFileInput():void{",
  );

if (
  start < 0 ||
  end < 0 ||
  end <= start
) {
  fail(
    "Nie znaleziono oczekiwanej funkcji addLibraryUi() w pack06/install.ts. Nic nie zmieniono.",
  );
}

const newLibraryUi =
  Buffer.from(
    "",
    "hex",
  ).toString(
    "utf8",
  );

pack06 =
  pack06.slice(
    0,
    start,
  ) +
  newLibraryUi +
  "\n\n" +
  pack06.slice(
    end,
  );

/*
  Give CSS a deterministic structural state instead of guessing
  whether a card is active from older cascading rules.
*/
const cardStateNeedle =
  'card.classList.toggle("is-on-scene",instances.length>0);';

if (
  !pack06.includes(
    cardStateNeedle,
  )
) {
  fail(
    "Nie znaleziono miejsca do oznaczenia stanu karty w decorateLibrary(). Przywróć backup z Pack 12.",
  );
}

pack06 =
  pack06.replace(
    cardStateNeedle,
    cardStateNeedle +
    'card.dataset.pack12Card="1";' +
    'card.dataset.pack12Active=instances.length>0?"1":"0";',
  );

const actionsNeedle =
  'const actions=document.createElement("div");actions.className="ae-pack06-card-actions";';

if (
  !pack06.includes(
    actionsNeedle,
  )
) {
  fail(
    "Nie znaleziono kontenera akcji kart. Przywróć backup z Pack 12.",
  );
}

pack06 =
  pack06.replace(
    actionsNeedle,
    'const actions=document.createElement("div");actions.className="ae-pack06-card-actions ae-pack12-card-actions";',
  );

fs.writeFileSync(
  pack06File,
  pack06,
  "utf8",
);

const cssPatch =
  Buffer.from(
    "",
    "hex",
  ).toString(
    "utf8",
  );

fs.writeFileSync(
  styleFile,
  currentStyle.trimEnd() +
  "\n\n" +
  cssPatch.trim() +
  "\n",
  "utf8",
);

const rollbackPath =
  path.join(
    root,
    "ae-ui-polish-pack-12-structural-rollback.mjs",
  );

const rollback =
`import fs from "node:fs";
import path from "node:path";

const root =
  process.cwd();

const backupRoot =
  ${JSON.stringify(
    backupRoot,
  )};

for (
  const relative of [
    ${JSON.stringify(
      styleRelative,
    )},
    ${JSON.stringify(
      pack06Relative,
    )},
  ]
) {
  const backup =
    path.join(
      backupRoot,
      relative,
    );

  const target =
    path.join(
      root,
      relative,
    );

  if (
    !fs.existsSync(
      backup,
    )
  ) {
    console.error(
      "Brak backupu:",
      backup,
    );
    process.exit(
      1,
    );
  }

  fs.copyFileSync(
    backup,
    target,
  );
}

console.log(
  "UI Polish Pack 12 cofnięty.",
);
`;

fs.writeFileSync(
  rollbackPath,
  rollback,
  "utf8",
);

console.log("");
console.log("======================================================");
console.log(" Animated Effects UI Polish Pack 12 STRUCTURAL INSTALLED");
console.log("======================================================");
console.log("");
console.log("Zakres: tylko UI/UX, bez zmian rendererów efektów.");
console.log("");
console.log("Naprawiono strukturalnie:");
console.log(" - Widok + Sortuj są teraz prawdziwym wspólnym rzędem DOM");
console.log(" - nieaktywne karty mają + naprawdę w prawej kolumnie");
console.log(" - aktywne karty zachowują osobny rząd - / licznik / +");
console.log(" - karty mają jawny stan data-pack12-active zamiast zgadywania CSS");
console.log(" - mniejsza wysokość kart i odstępy biblioteki");
console.log(" - usunięto rzeczywistą przyczynę zbyt wysokich pól inspectora (margin 15px z Pack08)");
console.log(" - Podstawowe i pozostałe grupy są bardziej zwarte");
console.log("");
console.log(
  "Backup:",
  path.relative(
    root,
    backupRoot,
  ),
);
console.log(
  "Rollback: .\\ae-ui-polish-pack-12-structural-rollback.mjs",
);
console.log("");
console.log("Teraz:");
console.log("  pnpm --filter animated-effects run typecheck");
console.log("  pnpm --filter animated-effects run build");
